1	type Cell = [number, number];
2	
3	const toKey = ([x, y]: Cell): string => `${x},${y}`;
4	const fromKey = (key: string): Cell => {
5	  const [x, y] = key.split(",").map(Number);
6	  return [x, y];
7	};
8	
9	const survivesNextGeneration = (isAlive: boolean, neighborCount: number): boolean =>
10	  isAlive ? neighborCount === 2 || neighborCount === 3 : neighborCount === 3;
11	
12	const neighborOffsets: Cell[] = [
13	  [-1, -1], [0, -1], [1, -1],
14	  [-1, 0],           [1, 0],
15	  [-1, 1], [0, 1], [1, 1],
16	];
17	
18	const countLivingNeighbors = (cells: Cell[]): Map<string, number> => {
19	  const counts = new Map<string, number>();
20	  for (const [x, y] of cells) {
21	    for (const [dx, dy] of neighborOffsets) {
22	      const key = toKey([x + dx, y + dy]);
23	      counts.set(key, (counts.get(key) ?? 0) + 1);
24	    }
25	  }
26	  return counts;
27	};
28	
29	export function nextGeneration(cells: Cell[]): Cell[] {
30	  const living = new Set(cells.map(toKey));
31	  const neighborCounts = countLivingNeighbors(cells);
32	
33	  const next: Cell[] = [];
34	  for (const [key, count] of neighborCounts) {
35	    if (survivesNextGeneration(living.has(key), count)) {
36	      next.push(fromKey(key));
37	    }
38	  }
39	  return next;
40	}
