const BIRTH_NEIGHBORS = 3;
const SURVIVAL_NEIGHBORS = [2, 3];

const survivesNextGeneration = (isAlive: boolean, neighborCount: number): boolean =>
  isAlive
    ? SURVIVAL_NEIGHBORS.includes(neighborCount)
    : neighborCount === BIRTH_NEIGHBORS;
